import{_ as p,c as d,a as l,b as s,d as e,e as a,w as r,r as o,o as u}from"./app-BHSdKjYv.js";const m="/aosai-blog/DeepLearning/EpochalAlgorithms/01_classification_space.png",c="/aosai-blog/DeepLearning/EpochalAlgorithms/01_classification_pipeline.png",b={},g={href:"https://arxiv.org/abs/1512.03385",target:"_blank",rel:"noopener noreferrer"},h={href:"https://arxiv.org/abs/1704.04861",target:"_blank",rel:"noopener noreferrer"},v={href:"https://arxiv.org/abs/1905.11946",target:"_blank",rel:"noopener noreferrer"},k={href:"https://arxiv.org/abs/2010.11929",target:"_blank",rel:"noopener noreferrer"},x={href:"https://arxiv.org/abs/2012.12877",target:"_blank",rel:"noopener noreferrer"},f={href:"https://arxiv.org/abs/2103.14030",target:"_blank",rel:"noopener noreferrer"},N={href:"https://github.com/openai/CLIP",target:"_blank",rel:"noopener noreferrer"},y={href:"https://arxiv.org/abs/2111.06377",target:"_blank",rel:"noopener noreferrer"},C={href:"https://arxiv.org/abs/2104.14294",target:"_blank",rel:"noopener noreferrer"},_={href:"https://arxiv.org/abs/2304.07193",target:"_blank",rel:"noopener noreferrer"},T={href:"https://github.com/huggingface/pytorch-image-models",target:"_blank",rel:"noopener noreferrer"};function L(w,n){const i=o("RouteLink"),t=o("ExternalLinkIcon");return u(),d("div",null,[n[41]||(n[41]=l(`<h2 id="_1-分类任务是什么" tabindex="-1"><a class="header-anchor" href="#_1-分类任务是什么"><span>1. 分类任务是什么？</span></a></h2><p>分类任务的目标很简单：<strong>给一个输入，判断它属于哪个类别</strong>。</p><p>如果只有两个类别，就是二分类；如果有很多类别，就是多分类。深度学习里的图像分类，就是把一张图片放进模型，让模型在一组固定类别里做选择：猫、狗、汽车、飞机……</p><p>但分类任务不是一上来就从图片开始的。先把维度降到最低，看它的本质会更清楚。</p><h3 id="_1-1-在-1-维空间中的分类" tabindex="-1"><a class="header-anchor" href="#_1-1-在-1-维空间中的分类"><span>1.1 在 1 维空间中的分类</span></a></h3><p>1 维空间里，每个样本只有一个数字。</p><p>比如我们只看一个人的身高，要判断他是“小孩”还是“成年人”。这时分类边界可以很简单：找一个阈值。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">身高 &lt; 140cm → 小孩</span>
<span class="line">身高 ≥ 140cm → 成年人</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>这个阈值就是分类边界。边界左边是一类，右边是另一类。</p><h3 id="_1-2-在-2-维空间中的分类" tabindex="-1"><a class="header-anchor" href="#_1-2-在-2-维空间中的分类"><span>1.2 在 2 维空间中的分类</span></a></h3><p>如果每个样本有两个数字，比如身高和体重，就进入了 2 维空间。</p><p>这时一个阈值不够了，我们需要一条线，把平面上的点分成两边。线的一边是类别 A，另一边是类别 B。</p><h3 id="_1-3-在-3-维空间中的分类" tabindex="-1"><a class="header-anchor" href="#_1-3-在-3-维空间中的分类"><span>1.3 在 3 维空间中的分类</span></a></h3><p>如果每个样本有三个数字，比如身高、体重、年龄，就进入了 3 维空间。</p><p>这时分类边界从一条线变成了一个平面。平面的一边是一类，另一边是另一类。</p><figure><img src="`+m+`" alt="Fig.1 分类任务的几何直觉：1D 用阈值，2D 用线，3D 用平面" width="560" tabindex="0" loading="lazy"><figcaption>Fig.1 分类任务的几何直觉：1D 用阈值，2D 用线，3D 用平面</figcaption></figure><p>维度继续升高后，我们就没法画出来了。但逻辑没有变：<strong>分类任务一直在找一个边界，把不同类别分开</strong>。</p><p>图像分类也是这样。只不过输入不再是 1 个数字，也不是 3 个数字，而是一整张图片。模型会先把整张图编码成一个特征向量，再根据这个向量判断：这张图更像猫、狗，还是汽车。</p><h2 id="_2-图像分类的算法抽象" tabindex="-1"><a class="header-anchor" href="#_2-图像分类的算法抽象"><span>2. 图像分类的算法抽象</span></a></h2><p>先给图像分类算法下一个定义：</p><blockquote><p><strong>图像分类算法，就是学习一个函数 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>f</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">f(x)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.10764em;">f</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span>，把一张图像 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span> 映射成一组类别概率。</strong></p></blockquote><p>如果类别集合是猫、狗、汽车，那么模型最后要输出的不是一句话，而是一个概率分布：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">P(猫 | 图像), P(狗 | 图像), P(汽车 | 图像)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这组概率加起来等于 1。谁的概率最大，模型就预测这张图属于谁。</p><p>所以图像分类的算法抽象可以写成：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">输入：一张图像 x</span>
<span class="line">输出：每个类别的概率 P(y | x)</span>
<span class="line">目标：让真实类别的概率尽可能高</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这就是分类任务在深度学习里的基本算法定义。后面的网络结构、损失函数、优化器，都是围绕这个定义服务的。从这个定义出发，图像分类的训练流程就很稳定：</p><figure><img src="`+c+'" alt="Fig.2 图像分类的训练闭环与预测输出" tabindex="0" loading="lazy"><figcaption>Fig.2 图像分类的训练闭环与预测输出</figcaption></figure><h3 id="_2-1-训练阶段-模型在循环里变好" tabindex="-1"><a class="header-anchor" href="#_2-1-训练阶段-模型在循环里变好"><span>2.1 训练阶段：模型在循环里变好</span></a></h3><p>拆开来看：</p><ol><li><strong>图像</strong>：输入是一张图片，形状通常是 <code>(C, H, W)</code>，比如 RGB 图像就是 3 个通道。</li><li><strong>特征提取器</strong>：CNN、ResNet、ViT 都是在这里工作，把像素变成更有用的特征。</li><li><strong>logits</strong>：模型给每个类别输出一个分数。</li><li><strong>交叉熵损失</strong>：看真实类别的分数有没有被模型推高。</li><li><strong>反向传播</strong>：根据损失计算梯度。</li><li><strong>优化器更新参数</strong>：参数更新后，模型进入下一批训练。</li></ol><p>训练不是走完一条线就结束，而是一个循环。每一批图片都会让模型调整一次参数；一个 epoch 结束后，模型会继续进入下一个 epoch，直到训练轮数结束。</p><h3 id="_2-2-预测阶段-训练结束后再输出类别" tabindex="-1"><a class="header-anchor" href="#_2-2-预测阶段-训练结束后再输出类别"><span>2.2 预测阶段：训练结束后再输出类别</span></a></h3>',33)),s("p",null,[n[1]||(n[1]=e("训练结束后，模型参数固定下来。此时再输入一张新图片，模型还是先输出 logits，然后用 ",-1)),a(i,{to:"/blogs/DeepLearning/ActivationFunction/06_SoftMax.html"},{default:r(()=>[...n[0]||(n[0]=[e("Softmax",-1)])]),_:1}),n[2]||(n[2]=e(" 把 logits 变成类别概率。",-1))]),n[42]||(n[42]=l(`<div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">图像 → 训练好的模型 → logits → Softmax → 类别概率 → 预测类别</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>所以要分清两件事：</p><ul><li><strong>训练时</strong>：重点是用损失函数和反向传播更新模型。</li><li><strong>预测时</strong>：重点是把 logits 变成概率，再取概率最大的类别。</li></ul><p>这就是图像分类最稳定的地方：<strong>后来的论文大多在改特征提取器，而不是改整套训练闭环</strong>。</p><h2 id="_3-图像分类里的固定组件" tabindex="-1"><a class="header-anchor" href="#_3-图像分类里的固定组件"><span>3. 图像分类里的固定组件</span></a></h2><p>图像分类的算法定义很稳定，所以很多组件也长期稳定。它们不是没有替代方案，而是默认组合已经很成熟。</p><h3 id="_3-1-输出形式-logits-softmax" tabindex="-1"><a class="header-anchor" href="#_3-1-输出形式-logits-softmax"><span>3.1 输出形式：logits + Softmax</span></a></h3><p>模型不会直接输出“猫”这个字。它会先给每个类别打一个分数，这个分数叫 <strong>logit</strong>。比如一张猫图进来，模型可能输出：</p><table><thead><tr><th>类别</th><th>小猫</th><th>小狗</th><th>汽车</th></tr></thead><tbody><tr><td>logit</td><td>5.2</td><td>1.1</td><td>-0.8</td></tr></tbody></table>`,9)),s("p",null,[n[4]||(n[4]=e("logit 可以比较大小，但它还不是概率。5.2 比 1.1 大，说明模型更倾向于“猫”，但 5.2 本身不能解释成“猫的概率是 5.2”。所以预测时需要 ",-1)),a(i,{to:"/blogs/DeepLearning/ActivationFunction/06_SoftMax.html"},{default:r(()=>[...n[3]||(n[3]=[e("Softmax",-1)])]),_:1}),n[5]||(n[5]=e("：",-1))]),n[43]||(n[43]=l(`<div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">logits → Softmax → 概率</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Softmax 会把所有类别的分数变成一组概率，并且这些概率加起来等于 1。</p><table><thead><tr><th>类别</th><th>小猫</th><th>小狗</th><th>汽车</th></tr></thead><tbody><tr><td>概率</td><td>0.97</td><td>0.02</td><td>0.01</td></tr></tbody></table><p>最后预测类别时，取概率最大的那个类别就行。</p><h3 id="_3-2-损失函数-crossentropyloss" tabindex="-1"><a class="header-anchor" href="#_3-2-损失函数-crossentropyloss"><span>3.2 损失函数：CrossEntropyLoss</span></a></h3><p>分类任务当然也在比较“预测”和“真实标签”的差距。只是这个差距，不是回归任务里的那种：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">预测值 - 真实值</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>因为分类标签不是连续数字。“猫”不是 1.0，“狗”也不是 2.0，它们只是类别名字。模型真正输出的是一组概率。如果真实标签是“猫”，我们希望模型输出：</p><table><thead><tr><th>类别</th><th>猫</th><th>狗</th><th>汽车</th></tr></thead><tbody><tr><td>理想概率</td><td>1</td><td>0</td><td>0</td></tr></tbody></table><p>这叫 <strong>one-hot 标签</strong>。它的意思是：真实类别那一项应该尽量接近 1，其他类别应该尽量接近 0。所以分类任务真正关心的是：</p><blockquote><p>真实类别的概率有没有被模型推高？</p></blockquote>`,11)),s("p",null,[n[7]||(n[7]=e("如果真实类别是“猫”，模型给“猫”的概率越接近 1，损失就越小；模型给“猫”的概率越接近 0，损失就越大。",-1)),a(i,{to:"/blogs/DeepLearning/LossFunction/02_CELoss.html"},{default:r(()=>[...n[6]||(n[6]=[e("交叉熵损失",-1)])]),_:1}),n[8]||(n[8]=e(" 正好做这件事：",-1))]),n[44]||(n[44]=l(`<ul><li>真实类别概率是 0.95：基本猜对，损失很小。</li><li>真实类别概率是 0.50：模型不太确定，损失中等。</li><li>真实类别概率是 0.01：模型几乎猜错，损失很大。</li></ul><p>所以在图像分类里，常见组合就是：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">logits + CrossEntropyLoss</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这里有一个 PyTorch 细节很重要：<code>nn.CrossEntropyLoss()</code> 内部已经包含了 <code>LogSoftmax</code>。所以训练时一般不要先手动写 <code>Softmax</code>，直接把 logits 交给损失函数就行。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line">logits <span class="token operator">=</span> model<span class="token punctuation">(</span>images<span class="token punctuation">)</span></span>
<span class="line">loss <span class="token operator">=</span> criterion<span class="token punctuation">(</span>logits<span class="token punctuation">,</span> labels<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-3-归一化-cnn-里长期以-batchnorm-为主" tabindex="-1"><a class="header-anchor" href="#_3-3-归一化-cnn-里长期以-batchnorm-为主"><span>3.3 归一化：CNN 里长期以 BatchNorm 为主</span></a></h3><p>图像分类模型通常会堆很多层卷积。层数一深，每一层看到的数据分布就容易变化，训练会变得不稳定。</p>`,7)),s("p",null,[n[10]||(n[10]=e("所以 CNN 分类模型里，",-1)),a(i,{to:"/blogs/DeepLearning/Normalization/01_BatchNorm.html"},{default:r(()=>[...n[9]||(n[9]=[e("BatchNorm",-1)])]),_:1}),n[11]||(n[11]=e(" 长期是默认选择。它放在卷积层附近，把一批数据的激活值拉回比较稳定的范围，让模型更容易训练。",-1))]),n[45]||(n[45]=l(`<p>常见结构是：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">Conv → BatchNorm → ReLU</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>后来 ViT 这类 Transformer 结构更多使用 LayerNorm，但在 CNN 图像分类这条线里，BatchNorm 仍然是最经典的归一化方式。</p><h3 id="_3-4-优化器-位置固定-选择有演进" tabindex="-1"><a class="header-anchor" href="#_3-4-优化器-位置固定-选择有演进"><span>3.4 优化器：位置固定，选择有演进</span></a></h3><p>优化器负责把梯度真正变成参数更新。它的位置很固定：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">loss.backward() → optimizer.step()</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>一轮训练可以写成很短的代码：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line"><span class="token keyword">for</span> images<span class="token punctuation">,</span> labels <span class="token keyword">in</span> dataloader<span class="token punctuation">:</span></span>
<span class="line">    logits <span class="token operator">=</span> model<span class="token punctuation">(</span>images<span class="token punctuation">)</span></span>
<span class="line">    loss <span class="token operator">=</span> criterion<span class="token punctuation">(</span>logits<span class="token punctuation">,</span> labels<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    optimizer<span class="token punctuation">.</span>zero_grad<span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    loss<span class="token punctuation">.</span>backward<span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    optimizer<span class="token punctuation">.</span>step<span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>对应到流程上，就是：</p><ol><li>输入一批图片</li><li>模型输出 logits</li><li>交叉熵计算损失</li><li>反向传播计算梯度</li><li>优化器更新参数，模型变成一个新版本</li><li>下一批图片继续进入这个新版本模型</li><li>重复很多轮，直到所有 epoch 结束</li></ol>`,10)),s("p",null,[n[13]||(n[13]=e("优化器本身有演进：早期常用 ",-1)),a(i,{to:"/blogs/DeepLearning/Optimizer/01_SGD.html"},{default:r(()=>[...n[12]||(n[12]=[e("SGD",-1)])]),_:1}),n[14]||(n[14]=e("，后来 Adam、AdamW 也很常见。但它没有改变图像分类的任务定义，只是在回答一个问题：",-1)),n[15]||(n[15]=s("strong",null,"参数应该怎么更新得更快、更稳？",-1))]),n[46]||(n[46]=l(`<p>训练结束后，才进入真正的预测流程：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line">logits <span class="token operator">=</span> model<span class="token punctuation">(</span>image<span class="token punctuation">)</span></span>
<span class="line">prob <span class="token operator">=</span> torch<span class="token punctuation">.</span>softmax<span class="token punctuation">(</span>logits<span class="token punctuation">,</span> dim<span class="token operator">=</span><span class="token number">1</span><span class="token punctuation">)</span></span>
<span class="line">pred <span class="token operator">=</span> prob<span class="token punctuation">.</span>argmax<span class="token punctuation">(</span>dim<span class="token operator">=</span><span class="token number">1</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这时模型不再更新参数，只输出最终类别。</p><h2 id="_4-图像分类里的主要变量-网络结构" tabindex="-1"><a class="header-anchor" href="#_4-图像分类里的主要变量-网络结构"><span>4. 图像分类里的主要变量：网络结构</span></a></h2><p>既然图像分类的算法定义和训练闭环这么稳定，为什么论文还在不断更新？答案是：<strong>主要在改特征提取器</strong>。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">图像 → 特征提取器 → logits</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>2015 年之后，图像分类的主战场逐渐从“怎样设计一个更强的 CNN”，转向了一个更大的问题：</p><blockquote><p>用什么方式，把一张图变成好用的视觉特征？</p></blockquote><p>这条线可以按真实生态分成三段。</p><h3 id="_4-1-2015-2019-监督训练的-cnn-backbone-仍是主力" tabindex="-1"><a class="header-anchor" href="#_4-1-2015-2019-监督训练的-cnn-backbone-仍是主力"><span>4.1 2015-2019：监督训练的 CNN backbone 仍是主力</span></a></h3>`,10)),s("p",null,[n[17]||(n[17]=e("2015 年之后，图像分类最重要的基线是 ",-1)),s("a",g,[n[16]||(n[16]=e("ResNet",-1)),a(t)]),n[18]||(n[18]=e("。它不是因为“更深”这两个字重要，而是因为它变成了后面很多视觉任务的默认骨干网络。当时的常见流程很直接：",-1))]),n[47]||(n[47]=l(`<div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">ImageNet 有标签数据</span>
<span class="line">→ 训练 CNN 分类器</span>
<span class="line">→ 去掉最后的分类头</span>
<span class="line">→ 把 CNN 当作下游任务的特征提取器</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这就是为什么 ResNet 不只是一个分类模型。它更像一个视觉特征工厂：检测、分割、检索，都可以先拿它做 backbone。</p>`,2)),s("p",null,[n[21]||(n[21]=e("工业界还关心速度和部署，于是 ",-1)),s("a",h,[n[19]||(n[19]=e("MobileNet",-1)),a(t)]),n[22]||(n[22]=e("、",-1)),s("a",v,[n[20]||(n[20]=e("EfficientNet",-1)),a(t)]),n[23]||(n[23]=e(" 这类模型变得重要。它们的共同目标不是单纯刷新分类准确率，而是在准确率、延迟、参数量之间找平衡。",-1))]),n[48]||(n[48]=s("p",null,"所以这一阶段可以这样概括：",-1)),n[49]||(n[49]=s("ul",null,[s("li",null,"ResNet：把 CNN backbone 变成稳定底座。"),s("li",null,"MobileNet：让分类模型能跑到移动端。"),s("li",null,"EfficientNet：系统地平衡深度、宽度、分辨率和算力。")],-1)),n[50]||(n[50]=s("h3",{id:"_4-2-2020-2021-transformer-开始替代-cnn-backbone",tabindex:"-1"},[s("a",{class:"header-anchor",href:"#_4-2-2020-2021-transformer-开始替代-cnn-backbone"},[s("span",null,"4.2 2020-2021：Transformer 开始替代 CNN backbone")])],-1)),s("p",null,[n[25]||(n[25]=e("2020 年，",-1)),s("a",k,[n[24]||(n[24]=e("ViT",-1)),a(t)]),n[26]||(n[26]=e(" 把图像分类的特征提取器换了一种写法：不再从卷积开始，而是把图片切成 patch，把 patch 当成 token。",-1))]),n[51]||(n[51]=l(`<div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">图像 → patch 序列 → Transformer → 分类 token → logits</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这一步很关键。分类算法没有变，还是输出 logits，还是可以用交叉熵训练；但中间的特征提取器从 CNN 换成了 Transformer。</p>`,2)),s("p",null,[s("a",x,[n[27]||(n[27]=e("DeiT",-1)),a(t)]),n[28]||(n[28]=e(" 解决了另一个现实问题：原始 ViT 很吃数据和算力，普通 ImageNet 训练不一定够。DeiT 通过数据增强和蒸馏，让 Transformer 在 ImageNet-1K 上也能训练得比较好。",-1))]),s("p",null,[s("a",f,[n[29]||(n[29]=e("Swin Transformer",-1)),a(t)]),n[30]||(n[30]=e(" 又把层级结构和局部窗口引回来，让 Transformer 不只适合分类，也适合检测、分割这类需要空间细节的任务。它的官方代码在视觉社区里也很常用。",-1))]),n[52]||(n[52]=s("p",null,"这一阶段的重点是：",-1)),n[53]||(n[53]=s("ul",null,[s("li",null,"ViT：证明 Transformer 可以直接做图像分类。"),s("li",null,"DeiT：让 ViT 更容易在常规数据规模上训练。"),s("li",null,"Swin：让 Transformer 成为通用视觉 backbone。")],-1)),n[54]||(n[54]=s("h3",{id:"_4-3-2021-之后-重点从-训练分类器-转向-预训练视觉表征",tabindex:"-1"},[s("a",{class:"header-anchor",href:"#_4-3-2021-之后-重点从-训练分类器-转向-预训练视觉表征"},[s("span",null,"4.3 2021 之后：重点从“训练分类器”转向“预训练视觉表征”")])],-1)),n[55]||(n[55]=s("p",null,[e("再往后看，很多热门工作已经不只是“训练一个 ImageNet 分类器”了，而是先训练一个强大的视觉编码器，再拿它去做分类、检索、检测、分割。"),s("strong",null,"这时，图像分类更像一个评测方式，而不是唯一目标。")],-1)),s("p",null,[s("a",N,[n[31]||(n[31]=e("CLIP",-1)),a(t)]),n[32]||(n[32]=e(" 是一个代表。它不是只用“图片-类别标签”训练，而是用“图片-文字”配对训练。预测时，可以把类别写成文本，比如 “a photo of a cat”，再比较图片特征和文本特征的相似度。CLIP 的论文和代码都非常有影响力。",-1))]),n[56]||(n[56]=l(`<div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">传统分类：图像 → 类别概率</span>
<span class="line">CLIP：图像特征 ↔ 文本特征</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div>`,1)),s("p",null,[s("a",y,[n[33]||(n[33]=e("MAE",-1)),a(t)]),n[34]||(n[34]=e(" 走的是自监督路线：遮住图片中的大部分 patch，让模型重建被遮住的部分。它不靠人工标签，也能学到可迁移的视觉特征。",-1))]),s("p",null,[s("a",C,[n[35]||(n[35]=e("DINO",-1)),a(t)]),n[37]||(n[37]=e(" 和 ",-1)),s("a",_,[n[36]||(n[36]=e("DINOv2",-1)),a(t)]),n[38]||(n[38]=e(" 也很重要。它们强调“不用人工标签，也能学到强视觉特征”。DINOv2 的目标更接近“通用视觉特征”，代码生态也很活跃。",-1))]),n[57]||(n[57]=l(`<p>这一阶段的变化，不只是网络结构变了，训练目标也变了：</p><ul><li>以前：用 ImageNet 标签训练分类器。</li><li>现在：先用大规模图文、自监督或弱监督数据训练视觉编码器。</li><li>分类：变成下游评测或应用方式之一。</li></ul><h3 id="_4-4-抽象总结-现在变的是-视觉编码器从哪里来" tabindex="-1"><a class="header-anchor" href="#_4-4-抽象总结-现在变的是-视觉编码器从哪里来"><span>4.4 抽象总结：现在变的是“视觉编码器从哪里来”</span></a></h3><p>如果只看早期 CNN，会以为图像分类论文主要在改“网络结构”。但看 2015 之后到现在，变化更准确地说是：</p><blockquote><p>图像分类的核心变量，从“设计一个 CNN”，变成了“选择或预训练一个视觉编码器”。</p></blockquote><p>可以这样对照：</p><table><thead><tr><th>阶段</th><th>代表工作</th><th>核心变化</th></tr></thead><tbody><tr><td>监督 CNN backbone</td><td>ResNet、MobileNet、EfficientNet</td><td>用有标签数据训练分类 backbone</td></tr><tr><td>Transformer backbone</td><td>ViT、DeiT、Swin</td><td>用 Transformer 替代 CNN 做视觉编码</td></tr><tr><td>大规模预训练表征</td><td>CLIP、MAE、DINOv2</td><td>先学通用视觉特征，再迁移到分类</td></tr></tbody></table><p>这也能和前面的网络结构系列对应起来：CNN 系列关注“视觉编码器怎么设计”；放到图像分类任务里看，视觉编码器已经从 CNN backbone 演进到了预训练基础模型。</p><p><strong>但无论编码器从哪里来，图像分类这个算法抽象仍然没有变</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">输入图像 → 输出类别概率 → 用真实标签监督训练</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="_5-图像分类的延伸" tabindex="-1"><a class="header-anchor" href="#_5-图像分类的延伸"><span>5. 图像分类的延伸</span></a></h2><h3 id="_5-1-和其他-cv-任务的关系" tabindex="-1"><a class="header-anchor" href="#_5-1-和其他-cv-任务的关系"><span>5.1 和其他 CV 任务的关系</span></a></h3><p>图像分类不是 CV 的全部，但它是很多任务的起点。</p><ul><li>图像分类：只判断整张图是什么。</li><li>语义分割：把分类从整张图扩展到每个像素。</li><li>目标检测：先判断“这里是不是物体”，再判断“它是什么类别”，还要回归边框。</li><li>实例分割：还要区分同一类别里的不同个体。</li></ul><p>所以图像分类是一个很好的起点。它先把最基础的问题讲清楚：</p><blockquote><p>给一个输入，输出它属于每个类别的概率。</p></blockquote><p>理解了这件事，后面再看语义分割、目标检测、实例分割，就不是从零开始，而是在看“分类任务又叠加了什么新要求”。</p><h3 id="_5-2-工程生态-timm-让-backbone-变成可选件" tabindex="-1"><a class="header-anchor" href="#_5-2-工程生态-timm-让-backbone-变成可选件"><span>5.2 工程生态：timm 让 backbone 变成可选件</span></a></h3><p>工业界和研究者现在常用的，往往不是某一篇论文的单独代码，而是模型库。</p>`,19)),s("p",null,[s("a",T,[n[39]||(n[39]=e("timm / pytorch-image-models",-1)),a(t)]),n[40]||(n[40]=e(" 就是典型例子。它收集了大量 PyTorch 图像编码器和 backbone，包括 ResNet、EfficientNet、ViT、Swin、ConvNeXt、MobileNet 等，是现在很常用的图像模型库。",-1))]),n[58]||(n[58]=l(`<p>它的价值不是提出一个新结构，而是把很多经典结构整理成统一接口。以前读一篇论文，可能要单独找作者代码、对齐预处理方式、加载权重；用了 timm 之后，很多模型可以用同一种方式创建：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line"><span class="token keyword">import</span> timm</span>
<span class="line"></span>
<span class="line">model <span class="token operator">=</span> timm<span class="token punctuation">.</span>create_model<span class="token punctuation">(</span><span class="token string">&quot;resnet50&quot;</span><span class="token punctuation">,</span> pretrained<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">,</span> num_classes<span class="token operator">=</span><span class="token number">10</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这背后其实反映了图像分类生态的成熟：模型结构越来越多，工程上更需要一个稳定的“模型货架”。研究者可以快速比较 backbone，工业界也可以更方便地挑选适合部署的模型。</p><p>实际开发中，很多时候不会从零实现 ResNet、ViT 或 Swin，而是直接从模型库里选一个 backbone：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">选择 backbone → 加分类头 → fine-tune / linear probe</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div>`,5))])}const S=p(b,[["render",L]]),j=JSON.parse('{"path":"/blogs/DeepLearning/EpochalAlgorithms/01_ImageClassification.html","title":"图像分类算法：流程稳定","lang":"en-US","frontmatter":{"title":"图像分类算法：流程稳定","date":"2026/06/27","categories":["跨时代算法"],"tags":["跨时代算法","图像分类","分类任务"]},"headers":[{"level":2,"title":"1. 分类任务是什么？","slug":"_1-分类任务是什么","link":"#_1-分类任务是什么","children":[{"level":3,"title":"1.1 在 1 维空间中的分类","slug":"_1-1-在-1-维空间中的分类","link":"#_1-1-在-1-维空间中的分类","children":[]},{"level":3,"title":"1.2 在 2 维空间中的分类","slug":"_1-2-在-2-维空间中的分类","link":"#_1-2-在-2-维空间中的分类","children":[]},{"level":3,"title":"1.3 在 3 维空间中的分类","slug":"_1-3-在-3-维空间中的分类","link":"#_1-3-在-3-维空间中的分类","children":[]}]},{"level":2,"title":"2. 图像分类的算法抽象","slug":"_2-图像分类的算法抽象","link":"#_2-图像分类的算法抽象","children":[{"level":3,"title":"2.1 训练阶段：模型在循环里变好","slug":"_2-1-训练阶段-模型在循环里变好","link":"#_2-1-训练阶段-模型在循环里变好","children":[]},{"level":3,"title":"2.2 预测阶段：训练结束后再输出类别","slug":"_2-2-预测阶段-训练结束后再输出类别","link":"#_2-2-预测阶段-训练结束后再输出类别","children":[]}]},{"level":2,"title":"3. 图像分类里的固定组件","slug":"_3-图像分类里的固定组件","link":"#_3-图像分类里的固定组件","children":[{"level":3,"title":"3.1 输出形式：logits + Softmax","slug":"_3-1-输出形式-logits-softmax","link":"#_3-1-输出形式-logits-softmax","children":[]},{"level":3,"title":"3.2 损失函数：CrossEntropyLoss","slug":"_3-2-损失函数-crossentropyloss","link":"#_3-2-损失函数-crossentropyloss","children":[]},{"level":3,"title":"3.3 归一化：CNN 里长期以 BatchNorm 为主","slug":"_3-3-归一化-cnn-里长期以-batchnorm-为主","link":"#_3-3-归一化-cnn-里长期以-batchnorm-为主","children":[]},{"level":3,"title":"3.4 优化器：位置固定，选择有演进","slug":"_3-4-优化器-位置固定-选择有演进","link":"#_3-4-优化器-位置固定-选择有演进","children":[]}]},{"level":2,"title":"4. 图像分类里的主要变量：网络结构","slug":"_4-图像分类里的主要变量-网络结构","link":"#_4-图像分类里的主要变量-网络结构","children":[{"level":3,"title":"4.1 2015-2019：监督训练的 CNN backbone 仍是主力","slug":"_4-1-2015-2019-监督训练的-cnn-backbone-仍是主力","link":"#_4-1-2015-2019-监督训练的-cnn-backbone-仍是主力","children":[]},{"level":3,"title":"4.2 2020-2021：Transformer 开始替代 CNN backbone","slug":"_4-2-2020-2021-transformer-开始替代-cnn-backbone","link":"#_4-2-2020-2021-transformer-开始替代-cnn-backbone","children":[]},{"level":3,"title":"4.3 2021 之后：重点从“训练分类器”转向“预训练视觉表征”","slug":"_4-3-2021-之后-重点从-训练分类器-转向-预训练视觉表征","link":"#_4-3-2021-之后-重点从-训练分类器-转向-预训练视觉表征","children":[]},{"level":3,"title":"4.4 抽象总结：现在变的是“视觉编码器从哪里来”","slug":"_4-4-抽象总结-现在变的是-视觉编码器从哪里来","link":"#_4-4-抽象总结-现在变的是-视觉编码器从哪里来","children":[]}]},{"level":2,"title":"5. 图像分类的延伸","slug":"_5-图像分类的延伸","link":"#_5-图像分类的延伸","children":[{"level":3,"title":"5.1 和其他 CV 任务的关系","slug":"_5-1-和其他-cv-任务的关系","link":"#_5-1-和其他-cv-任务的关系","children":[]},{"level":3,"title":"5.2 工程生态：timm 让 backbone 变成可选件","slug":"_5-2-工程生态-timm-让-backbone-变成可选件","link":"#_5-2-工程生态-timm-让-backbone-变成可选件","children":[]}]}],"git":{"createdTime":1782645602000,"updatedTime":1782645602000,"contributors":[{"name":"jinkai","email":"1213860588@qq.com","commits":1}]},"filePathRelative":"blogs/DeepLearning/EpochalAlgorithms/01_ImageClassification.md"}');export{S as comp,j as data};
